with session_totals as (select session_id, sum(case when page = '/product' then 1 else 0 end) product_count, sum(case when event_type = 'click' then 1 else 0 end) click_count from web_events where event_type <> 'search' group by session_id) select s.started_at, s.customer_id, st.product_count, st.click_count from sessions s left join session_totals st on s.id = st.session_id order by customer_id desc
